    },
    {
      "path": "docs/adr/0004-libghostty-terminal.md",
      "description": "libghostty-spm terminal integration, InMemoryTerminalSession, keyboard/touch-scroll/zoom ownership."
    },
    {
      "path": "docs/adr/0015-shell-terminal-via-direct-terminal-attach.md",
      "description": "Shell Terminal: tab.create + 'herdr terminal attach <id> --takeover' over the SSH PTY pipeline; herdr 0.8.2 facts."
    },
    {
      "path": "docs/adr/0016-direct-input-on-agent-attach.md",
      "description": "Opt-in Direct Input routing iOS keyboard into Agent Attach PTY."
    },
    {
      "path": "docs/adr/0009-snippets-insert-without-submitting.md",
      "description": "Snippets insert without submit; bracketed paste for multiline."
    },
    {
      "path": "docs/guides/vps-jump-host.md",
